:root {
  --bg-card: #f2ead8;
  --bg-header: #2c1f0e;
  --bg-body: #faf6ed;
  --bg-footer: #e8dfc8;
  --accent-rust: #8b3a1a;
  --accent-gold: #c4922a;
  --accent-olive: #5a6b2a;
  --accent-steel: #4a5c6e;
  --accent-pale: #d4c9a8;
  --text-dark: #1a1108;
  --text-light: #f2ead8;
  --text-muted: #7a6a4a;
  --olivine: #7a9a4a;
  --pyroxene: #8b7040;
  --metal-fe: #6a7a8a;
  --other: #c0a860;
  --border-main: #8b7040;
  --dot-color: #c0a860;
  --chondrule: #a07030;
}

body {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
}

.registry-card {
  width: 490px;
  background: var(--bg-card);
  border: 2px solid var(--border-main);
  border-radius: 4px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.card-header {
  background: var(--bg-header);
  padding: 8px 12px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  border-bottom: 3px solid var(--accent-gold);
}

.header-left {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.org-label {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.16em;
  color: var(--accent-gold);
  text-transform: uppercase;
}

.card-title {
  font-size: 16px;
  font-weight: 800;
  color: var(--text-light);
  margin: 0;
  line-height: 1.1;
}

.header-right {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 5px;
}

.specimen-id {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 1px;
}

.id-label {
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.14em;
  color: var(--accent-pale);
  text-transform: uppercase;
}

.id-value {
  font-size: 12px;
  font-weight: 700;
  color: var(--accent-gold);
  letter-spacing: 0.04em;
}

.class-badge {
  background: var(--accent-rust);
  color: var(--text-light);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  padding: 2px 7px;
  border-radius: 2px;
}

.card-body {
  display: flex;
  flex: 1;
  background: var(--bg-body);
}

.col-data {
  flex: 1;
  padding: 10px 12px;
  border-right: 1px solid var(--accent-pale);
}

.field-list {
  display: flex;
  flex-direction: column;
  gap: 0;
  margin: 0;
  padding: 0;
}

.field-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 8px;
  padding: 4px 0;
  border-bottom: 1px dotted var(--accent-pale);
}

.field-row:last-child {
  border-bottom: none;
}

.field-row dt {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.05em;
  color: var(--text-muted);
  text-transform: uppercase;
  white-space: nowrap;
}

.field-row dd {
  font-size: 11px;
  font-weight: 600;
  color: var(--text-dark);
  margin: 0;
  text-align: right;
}

.col-visual {
  width: 152px;
  padding: 10px 10px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
}

.specimen-figure {
  margin: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
}

.specimen-shape {
  width: 86px;
  height: 72px;
  background: var(--accent-rust);
  border-radius: 42% 58% 55% 45% / 48% 44% 56% 52%;
  border: 2px solid var(--border-main);
  position: relative;
  overflow: hidden;
}

.crust-layer {
  position: absolute;
  inset: 0;
  background: var(--bg-header);
  border-radius: 42% 58% 55% 45% / 48% 44% 56% 52%;
  opacity: 0.45;
}

.mineral-dot {
  position: absolute;
  border-radius: 50%;
  background: var(--dot-color);
}

.md1 { width: 7px; height: 7px; top: 18px; left: 16px; opacity: 0.7; }
.md2 { width: 5px; height: 5px; top: 38px; left: 50px; opacity: 0.6; }
.md3 { width: 6px; height: 6px; top: 50px; left: 26px; opacity: 0.65; }

.chondrule {
  position: absolute;
  border-radius: 50%;
  border: 2px solid var(--chondrule);
  background: transparent;
}

.ch1 { width: 16px; height: 16px; top: 26px; left: 34px; }
.ch2 { width: 11px; height: 11px; top: 10px; left: 50px; opacity: 0.7; }

figcaption {
  font-size: 9px;
  color: var(--text-muted);
  font-style: italic;
  text-align: center;
}

.composition-bar {
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.bar-label {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--text-muted);
}

.bar-track {
  display: flex;
  height: 14px;
  border-radius: 2px;
  overflow: hidden;
  border: 1px solid var(--border-main);
}

.bar-seg {
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 8px;
  font-weight: 800;
  color: var(--text-light);
  letter-spacing: 0.03em;
}

.seg-olivine  { background: var(--olivine);  flex: 3; }
.seg-pyroxene { background: var(--pyroxene); flex: 2.5; }
.seg-metal    { background: var(--metal-fe); flex: 1.5; }
.seg-other    { background: var(--other);    flex: 1; color: var(--text-dark); }

.card-footer {
  background: var(--bg-footer);
  border-top: 2px solid var(--accent-gold);
  padding: 6px 12px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.footer-left {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.classifier-label {
  font-size: 8px;
  color: var(--text-muted);
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.classifier-name {
  font-size: 11px;
  font-weight: 700;
  color: var(--text-dark);
}

.stamp-row {
  display: flex;
  gap: 5px;
}

.verified-stamp,
.catalog-stamp {
  font-size: 8px;
  font-weight: 900;
  letter-spacing: 0.1em;
  padding: 2px 6px;
  border-radius: 2px;
  text-transform: uppercase;
}

.verified-stamp {
  border: 2px solid var(--accent-olive);
  color: var(--accent-olive);
}

.catalog-stamp {
  border: 2px solid var(--accent-steel);
  color: var(--accent-steel);
}
